// The East Side Athletic Clubs wordmark, inlined as a data URI.
//
// Milwaukie trades as ESAC, so its board carries this mark instead of the WCS
// badge. Inlined for the same reason as ./wcsMark: a logo that 404s on a
// wall-mounted screen is worse than no logo at all.
//
// Source is auth/src/templates/day-one/logo-esac.png (1437px, the Day One
// program mark), downscaled to 640px wide. The board caps the logo at 112 CSS
// px tall, and this ~3.3:1 mark is ~370px wide at that height, so 640px leaves
// ~1.7x for a high-DPR panel. It keeps its own colours (tan bar, grey sphere):
// the black-and-white ESAC look applies to the board's accents, not the mark,
// which has no legible one-colour version.
const ESAC_MARK_DATA_URI = 'data:image/png;base64,'

module.exports = { ESAC_MARK_DATA_URI }
